const raw = JSON.parse($input.first().json.response || '{}');
let sql = String(raw.sql || '').trim().replace(/;+$/, '');
const forbidden = /\b(INSERT|UPDATE|DELETE|DROP|ALTER|TRUNCATE|GRANT|REVOKE|COPY|CREATE|EXEC|INTO|pg_sleep)\b/i;
if (!/^SELECT\b/i.test(sql) || forbidden.test(sql) || sql.includes(';')) {
  throw new Error('SECURITY_BLOCK: Only single-statement read-only SELECT queries are permitted.');
}
if (!/\bLIMIT\s+\d+/i.test(sql)) {
  sql += ' LIMIT 100';
}
return [{ json: { verifiedSql: sql } }];
